function initMarketplace(){const filterBtns=document.querySelectorAll(".marketplace-filter-btn");const serviceFilterBtns=document.querySelectorAll(".service-filter-btn");function updateActiveFilter(category){activeMarketplaceCategory=category;filterBtns.forEach(btn=>{if(btn.getAttribute("data-category")===category){btn.classList.add("active");btn.style.background="var(--accent-gold)";btn.style.color="#000000";btn.style.borderColor="var(--accent-gold)";}else{btn.classList.remove("active");btn.style.background="rgba(13, 21, 39, 0.8)";btn.style.color="var(--text-primary)";btn.style.borderColor="var(--border-color)";}});renderMarketplaceListings();}
function updateActiveServiceFilter(category){activeServicesCategory=category;serviceFilterBtns.forEach(btn=>{if(btn.getAttribute("data-category")===category){btn.classList.add("active");btn.style.background="#3b82f6";btn.style.color="#ffffff";btn.style.borderColor="#3b82f6";}else{btn.classList.remove("active");btn.style.background="rgba(13, 21, 39, 0.8)";btn.style.color="var(--text-primary)";btn.style.borderColor="var(--border-color)";}});renderServicesListings();}
if(filterBtns.length){filterBtns.forEach(btn=>{btn.style.cursor="pointer";btn.style.transition="all 0.2s ease";btn.addEventListener("click",()=>{const category=btn.getAttribute("data-category");updateActiveFilter(category);});btn.addEventListener("mouseover",()=>{if(!btn.classList.contains("active")){btn.style.background="rgba(255, 255, 255, 0.1)";}else{btn.style.opacity="0.85";}});btn.addEventListener("mouseout",()=>{if(!btn.classList.contains("active")){btn.style.background="rgba(13, 21, 39, 0.8)";}else{btn.style.opacity="1";}});});}
if(serviceFilterBtns.length){serviceFilterBtns.forEach(btn=>{btn.style.cursor="pointer";btn.style.transition="all 0.2s ease";btn.addEventListener("click",()=>{const category=btn.getAttribute("data-category");updateActiveServiceFilter(category);});btn.addEventListener("mouseover",()=>{if(!btn.classList.contains("active")){btn.style.background="rgba(255, 255, 255, 0.1)";}else{btn.style.opacity="0.85";}});btn.addEventListener("mouseout",()=>{if(!btn.classList.contains("active")){btn.style.background="rgba(13, 21, 39, 0.8)";}else{btn.style.opacity="1";}});});}
[filterBtns,serviceFilterBtns].forEach(group=>{if(group.length&&group[0].parentElement){const parent=group[0].parentElement;parent.style.userSelect="none";parent.style.webkitUserSelect="none";function applyResponsiveFilterLayout(){if(window.innerWidth<=768){parent.style.flexWrap="nowrap";parent.style.overflowX="auto";parent.style.webkitOverflowScrolling="touch";parent.style.scrollbarWidth="none";parent.style.paddingBottom="4px";group.forEach(btn=>{btn.style.flexShrink="0";btn.style.whiteSpace="nowrap";});}else{parent.style.flexWrap="wrap";parent.style.overflowX="visible";parent.style.paddingBottom="0px";}}
applyResponsiveFilterLayout();window.addEventListener("resize",applyResponsiveFilterLayout);}});if(filterBtns.length)updateActiveFilter(activeMarketplaceCategory);if(serviceFilterBtns.length)updateActiveServiceFilter(activeServicesCategory);const urlParams=new URLSearchParams(window.location.search);const targetId=urlParams.get('id')||(window.location.hash?window.location.hash.replace('#',''):null);if(targetId&&typeof marketplaceListings!=='undefined'){const matchedItem=marketplaceListings.find(item=>item.id===targetId);if(matchedItem&&matchedItem.images&&matchedItem.images.length>0){setTimeout(()=>{if(typeof window.openImageModal==='function'){window.openImageModal(matchedItem.images,matchedItem.title);}},150);}}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initMarketplace);}else{initMarketplace();}